arguments.workflowScript:
const papers = await runs.all([
  {key:'v2', agent:'researcher', task:'In /workspace/2026/LUCID3_wikit, deeply read docs/papers/2020_dreamerv2.md, not only its abstract or introduction. Extract the strongest exact quotations needed to define what makes Dreamer latent dynamics useful for planning: model state, posterior/prior or observation boundary, action conditioning, imagination, objective, long-horizon evaluation, ablations, and limitations. Cite local file section and line numbers if possible. Separate author observations from your inference. Relate each point cautiously to LUCID3 residual prediction. Do not edit files.'},
  {key:'v3', agent:'researcher', task:'In /workspace/2026/LUCID3_wikit, deeply read docs/papers/2023_dreamerv3.md, not only its abstract or introduction. Extract exact quotations needed to define and test a plannable latent dynamics state: representation learning, dynamics/reconstruction/reward objectives, action-conditioned imagination, long-horizon prediction, policy learning, ablations, and failure prevention. Cite local file section and line numbers if possible. Separate author observations from your inference. Relate each point cautiously to LUCID3. Do not edit files.'},
  {key:'v4', agent:'researcher', task:'In /workspace/2026/LUCID3_wikit, deeply read docs/papers/2025_dreamer4.md, not only its abstract or introduction. Extract exact quotations needed to define and test a plannable latent dynamics state: representation prediction, autoregressive rollout, actions, causality, planning/control training, evaluation and ablations. Cite local file section and line numbers if possible. Separate author observations from your inference. Relate each point cautiously to LUCID3. Do not edit files.'}
]);
const synthesisTask = `We need advise a researcher designing LUCID3. Ultimate goal: extract a compact plannable latent dynamics model from frozen LLM residual trajectories. Current spec predicts future final-layer residual states from a causal prefix of middle-layer states on WikiText. The user wants concrete mockups that a dumber model can imagine: (a) short causal proof akin Anthropic J-lens figures, perhaps higher F1; (b) long-horizon planning, previously a text maze; and questions whether interventions/actions/planning must wait until after first experiment. Read these three paper reports below, then propose a minimal staged evidence program. Distinguish prediction, causal representation evidence, autonomous rollout, and planning. Specify diagrams/mockups, controls, metrics, and discriminators. Assess maze planning versus replicating J-lens figures. Preserve exact quotations and citations from reports. Do not edit files.

V2 REPORT:
${papers[0]}

V3 REPORT:
${papers[1]}

V4 REPORT:
${papers[2]}`;
const synthesis = await runs.run('synthesis', {agent:'oracle', task:synthesisTask});
return {v2: papers[0], v3: papers[1], v4: papers[2], synthesis};

